const $ = s => document.querySelector(s);
const colors=['var(--t1)','var(--t2)','var(--t3)','var(--t4)'];
const names=['First light','Slow emergence','Open water','Afterglow','Suspended','Distant voices','Low tide','Passing through','Still air','Returning','Soft edges','Nightfall'];
let scenes=[],selected=null,concept='a',serial=0;
const overlays=new Set();
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function makeScene(){const n=serial++;return {id:n,name:names[n%names.length],bars:[8,16,32,16][n%4],nodes:n%3+2,transition:8,blend:65,curve:40};}
function preset(n){serial=0;scenes=Array.from({length:n},makeScene);selected=scenes[Math.min(1,n-1)].id;render();$('#status').textContent=`${n} dummy Scenes loaded`;}
function dots(n){return `<span class="dots">${colors.slice(0,n).map(c=>`<i class="dot" style="--color:${c}"></i>`).join('')}</span>`;}
function render(){
 $('#scenes').className=concept;
 $('#scenes').innerHTML=scenes.map((s,i)=>`<button class="scene ${s.id===selected?'selected':''}" data-id="${s.id}" aria-pressed="${s.id===selected}"><span class="row"><span class="num">${String(i+1).padStart(2,'0')}</span><span class="name">${escapeHTML(s.name)}</span><span class="duration">${s.bars}<small> b</small></span></span>${concept==='b'?`<span class="mini-mixer" aria-hidden="true">${colors.slice(0,s.nodes).map((c,j)=>`<i class="mini-meter" style="--color:${c};--level:${8+(s.id+j)%3*5}px"></i>`).join('')}</span>`:''}<span class="metadata">${dots(s.nodes)}<span class="contents">${s.nodes} nodes · ${s.nodes===2?'sample / field':'sample / synth / field'}</span></span></button>`).join('') || '<p class="hint">Capture a first moment.</p>';
 $('#total').textContent=`${scenes.length} / ${scenes.reduce((a,s)=>a+s.bars,0)} BARS`;
 $('#description').textContent={a:'A / Scene cards — contents at a glance.',b:'B / Mini strips — a small, frozen configuration.',c:'C / Weave spine — sequence first; detail on selection.'}[concept];
 const s=scenes.find(s=>s.id===selected),i=scenes.indexOf(s),next=scenes[i+1];
 $('#editor').innerHTML=s?`<span class="num">SCENE ${String(i+1).padStart(2,'0')}</span><label class="field">Name <input id="rename" type="text" maxlength="40" value="${escapeHTML(s.name)}"></label><label class="field">Duration · bars <input id="duration" type="number" min="1" max="999" value="${s.bars}"></label><button class="delete" id="delete">− Delete Scene</button>`:'';
 $('#transition').innerHTML=s?`<div class="endpoint"><span class="num">${String(i+1).padStart(2,'0')}</span><strong>${escapeHTML(s.name)}</strong></div>${next?`<div class="route">↓ <span id="bar-value">${s.transition}</span> bars</div><div class="endpoint"><span class="num">${String(i+2).padStart(2,'0')}</span><strong>${escapeHTML(next.name)}</strong></div><label class="field">Transition length <input id="transition-bars" aria-label="Transition bars" type="number" min="1" max="64" value="${s.transition}"></label><div class="knobs">${knob('Blend',s.blend,'blend')}${knob('Curve',s.curve,'curve')}</div><p class="hint">An imagined passage between these two moments. Move the controls to explore the surface.</p>`:'<div class="route">↓ End of sequence</div><p class="hint">Capture another Scene to explore the next transition.</p>'}`:'<p class="hint">Select a Scene to see its next passage.</p>';
 if(s){$('#rename').onchange=e=>{s.name=e.target.value.trim()||'Untitled';render();};$('#duration').onchange=e=>{s.bars=Math.max(1,Math.min(999,Math.round(Number(e.target.value)||1)));render();};$('#delete').onclick=()=>{scenes.splice(i,1);selected=scenes[Math.min(i,scenes.length-1)]?.id??null;render();};}
 if(next){$('#transition-bars').onchange=e=>{s.transition=Math.max(1,Math.min(64,Math.round(Number(e.target.value)||1)));render();};['blend','curve'].forEach(key=>{$('#'+key).oninput=e=>{s[key]=Number(e.target.value);e.target.previousElementSibling.textContent=s[key]+'%';};});}
}
function knob(label,value,id){return `<label class="knob-control"><div class="knob" aria-hidden="true"></div>${label}<div>${value}%</div><input type="range" min="0" max="100" value="${value}" ${id?`id="${id}"`:''} aria-label="${label}"></label>`;}
$('#scenes').onclick=e=>{const b=e.target.closest('[data-id]');if(b){selected=Number(b.dataset.id);render();}};
document.querySelectorAll('[data-concept]').forEach(b=>b.onclick=()=>{concept=b.dataset.concept;document.querySelectorAll('[data-concept]').forEach(t=>t.setAttribute('aria-pressed',t===b));render();});
$('#count').onchange=e=>preset(Number(e.target.value));
$('#capture').onclick=()=>{const s=makeScene();scenes.push(s);selected=s.id;render();$('#scenes').lastElementChild.scrollIntoView({block:'nearest'});$('#status').textContent=`Captured Scene ${scenes.length} · dummy state only`;};
$('#theme').onclick=()=>document.body.classList.toggle('dark');
$('.channels').innerHTML=colors.map((c,i)=>`<button data-track="${i}" aria-label="Channel ${i+1} controls" aria-pressed="false"><i class="orb" style="--color:${c}"></i></button>`).join('');
function toggleTrack(i){if(overlays.has(i))overlays.delete(i);else overlays.add(i);renderOverlays();}
function renderOverlays(){['left','right'].forEach((side,k)=>{$('#'+side+'-overlays').innerHTML=[k*2,k*2+1].map((i,j)=>overlays.has(i)?`<article class="strip" style="grid-row:${j+1};--color:${colors[i]}" aria-label="Channel ${i+1} overlay"><div class="strip-head"><b>${i+1}</b><strong>${['Field recording','Tick Tok','Prism cloud','Singing bowl'][i]}</strong><button data-close="${i}" aria-label="Close channel ${i+1}">×</button></div><div class="sources"><span>◌ Sample</span><span>◇ Node</span><span>↗ Stream</span><span>＋ Input</span></div><div class="timer">02:48</div><div class="strip-note">DUMMY CHANNEL · ${i+1}</div><div class="knobs">${knob('Low',50)}${knob('Mid',50)}${knob('High',50)}</div><label class="field">Channel gain <span>0 dB</span></label><input type="range" aria-label="Channel ${i+1} gain" value="72"><p class="hint">Close this strip to reveal ${side==='left'?'Weave':'the transition'} underneath.</p></article>`:'').join('');});document.querySelectorAll('.channels [data-track]').forEach(b=>b.setAttribute('aria-pressed',overlays.has(Number(b.dataset.track))));}
document.addEventListener('click',e=>{const b=e.target.closest('[data-track]');if(b)toggleTrack(Number(b.dataset.track));const close=e.target.closest('[data-close]');if(close)toggleTrack(Number(close.dataset.close));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){overlays.clear();renderOverlays();}});
preset(4);
